import{_ as o,o as e,c as d,ag as a}from"./chunks/framework.BaNuf0sO.js";const p=JSON.parse('{"title":"FormSubmitPanel（提交表单面板）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/form/docs/README-FormSubmitPanel.md","filePath":"docs/core/src/components/form/docs/README-FormSubmitPanel.md"}'),i={name:"docs/core/src/components/form/docs/README-FormSubmitPanel.md"};function r(s,t,c,n,l,h){return e(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="formsubmitpanel-提交表单面板" tabindex="-1">FormSubmitPanel（提交表单面板） <a class="header-anchor" href="#formsubmitpanel-提交表单面板" aria-label="Permalink to &quot;FormSubmitPanel（提交表单面板）&quot;">​</a></h1><blockquote><p>FormMain 的提交面：<code>stringifyData</code> 作初值 + 内置「校验 → 序列化 → 提交」管线 + 取消 / 重置 / 提交操作区（可插槽替换），success / fail / parseDataChange 三事件闭环。 范式页：<code>apps/reference/src/pages/form/submit-panel/showcase/</code></p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>空间一等公民</strong>：纯表单提交空间首选（表单页 / 弹窗内表单）——业务层能用 FormMain 处用 FormSubmitPanel 替代</li><li><strong>何时用</strong>：录入 / 编辑弹窗或页面的表单主体——需要完整提交管线 + 操作区</li><li><strong>何时不用</strong>：纯查询 / 搜索用 <code>FormSearch</code>；仅录入无提交操作区用 <code>FormMain</code>；只要一个提交按钮（无面板壳）用 <code>FormSubmitBtn</code> 挂 FormMain</li><li>与 FormMain 的差异：<code>data</code> 被 Omit——表单值由 <code>stringifyData</code> 初值内部管理（优先 <code>parseFormData</code> 回填，否则 <code>generateFormData</code> 初始化），消费方不持有 data</li><li>内置组合：<code>FormSubmitBtn</code>（提交按钮，validate → stringify → submitFn → loading 管线）；<code>inheritAttrs: false</code>，attrs 转发内层 FormMain</li></ul><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>单面板最小形态（list + stringifyData 回填 + submitFn + 成功 / 失败回调即完整）：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">FormSubmitPanel</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;list&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :stringifyData</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;seed&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :submitFn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;submitFn&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  @success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;onSuccess&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> @fail</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;onFail&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><p><strong>要点</strong>：</p><ul><li><code>submitFn</code> 收 <code>stringifyData</code> 返回 Promise——提交成功后 <code>@success</code> 直接透传同一 <code>stringifyData</code> 载荷（新增 / 编辑区分由消费方按上下文定）</li><li><code>stringifyData</code> 作初值：回填数据直接给序列化形态，面板内部消化解析 / 初始化（不传则 <code>generateFormData(list)</code> 初始化）</li><li>校验 → 序列化 → 提交 → loading 管线内置，消费方零接线；<code>@parse-data-change</code> 回传内部解析模型（如 reset 后），供外部联动</li></ul><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>默认即够用：<code>list</code> + <code>submitFn</code> + <code>@success</code> / <code>@fail</code> 即为完整提交面板</strong>（无回填时 <code>stringifyData</code> 可省，内部 <code>generateFormData</code> 初始化）。</li><li><code>cancelBtn</code> / <code>resetBtn</code>：默认未设 = 不展示；仅当需要取消 / 重置操作才设按钮文字（按钮顺序固定：取消 → 重置 → 提交）。</li><li><code>operationPosition</code>：默认 <code>bottom-center</code> 即够用；仅当面板布局需要（如页内表单放右下）才改。</li><li><code>operationAffix</code>：默认关；仅当长表单提交区需要吸底固定才开（<code>true</code>=吸底 <code>position: &quot;bottom&quot;</code>，对象=ElAffix 原样透传）。</li><li><code>submitBtnProps</code>：默认 primary 即够用；仅当需改提交按钮形态（size / 其他 ButtonProps）才设。</li><li><code>#cancelBtn</code> / <code>#resetBtn</code> / <code>#submitBtn</code> 三插槽：默认关；仅当按钮需完全自定义时开（<code>#submitBtn</code> 接内置校验 + 序列化 + 提交管线）。</li><li><code>divider</code> / <code>bare</code> / <code>rootClass</code>：默认即够用；仅当面板视觉定制（去分割线 / 去内边距 / 根类定向）才动。</li><li><strong>完整能力演示</strong>（操作区三态 + 插槽替换 + 图钉）：<code>apps/reference/src/pages/form/submit-panel/showcase/</code>——能力展示，非推荐默认。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props-泛型-po-解析-so-格式化-formsubmitpanelprops-po-so-omit-formmainprops-data-提交相关" tabindex="-1">Props（泛型 <code>PO</code> 解析 / <code>SO</code> 格式化，<code>FormSubmitPanelProps&lt;PO, SO&gt;</code> = <code>Omit&lt;FormMainProps, &quot;data&quot;&gt;</code> + 提交相关） <a class="header-anchor" href="#props-泛型-po-解析-so-格式化-formsubmitpanelprops-po-so-omit-formmainprops-data-提交相关" aria-label="Permalink to &quot;Props（泛型 `PO` 解析 / `SO` 格式化，`FormSubmitPanelProps&lt;PO, SO&gt;` = `Omit&lt;FormMainProps, &quot;data&quot;&gt;` + 提交相关）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>FormItemConfigList</code>（必填）</td><td>—</td><td>透传 FormMain</td></tr><tr><td><code>layout</code></td><td><code>Partial&lt;ColProps&gt;</code></td><td><code>{span: 24}</code></td><td>透传（默认单列）</td></tr><tr><td><code>rowGutter</code> / <code>layoutScale</code></td><td>同 FormMain</td><td>—</td><td>已声明 prop 不入 attrs 且未显式转发——<strong>实际被丢弃</strong>（layoutScale / layoutByContainer 均不生效）</td></tr><tr><td><code>stringifyData</code></td><td><code>ExcludeNeverProperties&lt;ExtractFormStringifyRawFromObject&lt;PO, SO&gt;&gt;</code></td><td>未设</td><td>序列化数据作初值（优先 <code>parseFormData</code> 回填，否则 <code>generateFormData</code> 初始化）</td></tr><tr><td><code>submitText</code></td><td><code>string</code></td><td>未设</td><td>提交按钮文本</td></tr><tr><td><code>submitFn</code></td><td><code>(stringifyData) =&gt; Promise&lt;unknown&gt;</code>（必填）</td><td>—</td><td>提交方法</td></tr><tr><td><code>submitBtnProps</code></td><td><code>Omit&lt;FormSubmitBtnProps, &quot;submitText&quot; | &quot;submitFn&quot; | &quot;formMainInstance&quot;&gt;</code></td><td>未设</td><td>内置 FormSubmitBtn 的额外 ButtonProps（如 <code>{ type: &#39;primary&#39; }</code>）</td></tr><tr><td><code>labelPosition</code></td><td><code>&quot;right&quot; | &quot;left&quot; | &quot;top&quot;</code></td><td><code>&quot;right&quot;</code></td><td>标签位置</td></tr><tr><td><code>labelWidth</code></td><td><code>string</code></td><td><code>&quot;auto&quot;</code></td><td>标签宽度</td></tr><tr><td><code>cancelBtn</code></td><td><code>string</code></td><td>未设</td><td>取消按钮文字（空则不展示；同名插槽优先）</td></tr><tr><td><code>resetBtn</code></td><td><code>string</code></td><td>未设</td><td>重置按钮文字（警告色；同名插槽优先）</td></tr><tr><td><code>operationPosition</code></td><td><code>&quot;bottom-center&quot; | &quot;bottom-right&quot; | &quot;top-right&quot;</code></td><td><code>&quot;bottom-center&quot;</code></td><td>操作区位置</td></tr><tr><td><code>operationAffix</code></td><td><code>boolean | AffixProps</code></td><td><code>false</code></td><td>操作区图钉（<code>true</code>=吸底 <code>position: &quot;bottom&quot;</code>；对象=原样透传 ElAffix）</td></tr><tr><td><code>divider</code></td><td><code>boolean</code></td><td><code>true</code></td><td>操作区分隔线 + 圆角</td></tr><tr><td><code>bare</code></td><td><code>boolean</code></td><td><code>false</code></td><td>去操作区内边距（与 divider 正交）</td></tr><tr><td><code>rootClass</code></td><td><code>string | string[] | Record&lt;string, boolean&gt;</code></td><td>未设</td><td>根面板自定义 class（<code>inheritAttrs: false</code> 下 class 会透传内层 FormMain，本 prop 是显式根出口）</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>语义</th></tr></thead><tbody><tr><td><code>cancel</code></td><td>—</td><td>取消触发</td></tr><tr><td><code>fail</code></td><td><code>error: any</code></td><td>提交失败（submitFn reject）</td></tr><tr><td><code>success</code></td><td><code>FormDataInfo[&quot;stringifyData&quot;]</code></td><td>提交成功（submitFn resolve，透传 stringifyData 载荷）</td></tr><tr><td><code>parseDataChange</code></td><td><code>PO</code></td><td>内部 parseData 变化（reset 只内部 set parseData，经此事件通知外部）</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table tabindex="0"><thead><tr><th>槽</th><th>scope</th><th>语义</th></tr></thead><tbody><tr><td><code>#cancelBtn</code></td><td><code>{ cancel }</code></td><td>替换取消按钮（cancelBtn 为空时也可经此插自定义取消）</td></tr><tr><td><code>#resetBtn</code></td><td><code>{ reset }</code></td><td>替换重置按钮</td></tr><tr><td><code>#submitBtn</code></td><td><code>{ submit, submitting }</code></td><td>替换提交按钮（接内置校验 + 序列化 + 提交管线，可全替换按钮）</td></tr><tr><td><code>#&lt;config.key&gt;</code></td><td>FormItem 内部 mainProps</td><td>覆盖单项（透传 FormMain）</td></tr></tbody></table><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无（表单实例内置，不对外暴露 ref 方法）。</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>外部传 <code>data</code></strong>：类型已 Omit（<code>Omit&lt;FormMainProps, &quot;data&quot;&gt;</code>）——表单值由 <code>stringifyData</code> 初值内部管理，外部回填走 <code>stringifyData</code>，联动走 <code>@parse-data-change</code></li><li><strong><code>layoutByContainer</code> / <code>layoutScale</code> 无效</strong>：已声明 prop 不入 attrs 且未显式转发——确定不生效；容器断点场景用 FormMain 或 FormSearch（其 layoutByContainer 显式转发）</li><li><strong>手工拼提交载荷</strong>：<code>submitFn</code> 收的即是序列化形态，<code>@success</code> 同载荷透传——提交 / 回传 / 回填三段共用同一 <code>stringifyData</code>，勿在中间自造转换</li><li><strong>reset 语义</strong>：reset 只内部 set parseData（回到初值快照，初值来自 <code>stringifyData</code> 或缺省 <code>generateFormData</code>），非清空到空白——需要空白态直接重给 <code>stringifyData</code></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>表单族：<code>FormMain</code>（底座）、<code>FormSubmitBtn</code>（内置提交按钮，经 <code>submitBtnProps</code> 定制）、<code>FormSearch</code>（搜索面）</li><li>类型：<code>FormDataInfo&lt;PO, SO&gt;</code> = <code>{ parseData, stringifyData }</code>（success / parseDataChange 载荷）；<code>ExtractFormStringifyRawFromObject</code>（类型级提取）</li><li>范式页：<code>apps/reference/src/pages/form/submit-panel/showcase/</code></li></ul>',25)])])}const u=o(i,[["render",r]]);export{p as __pageData,u as default};
